var m = tree.current_scene
var found = []
for n in m.find_children("*", "", true, false):
	if str(n.name).to_lower().contains("difficulty"):
		found.append(str(n.name))
	elif n is Label and n.text.ends_with("AI Difficulty:"):
		found.append("label:" + n.text)
	elif n is OptionButton:
		for i in range(n.item_count):
			if n.get_item_text(i) in ["Easy", "Competitive"]:
				found.append("option:%s/%s" % [n.name, n.get_item_text(i)])
return ",".join(found)

var cfg = GameState.state.meta.get("game_config", {})
var keys = []
for k in cfg.keys():
	if str(k).contains("difficulty"):
		keys.append(str(k))
return ",".join(keys)
